rename(204,1,"Катада ибн Ну'ман в рассказе о краже у Рифаа и обвинении невиновного",'Имя не названо в аятах; связь основана на переданном рассказе, а не на отождествлении Катады с грешником.')
evidence=src('tirmidhi-3036','Джами ат-Тирмизи, 3036','https://sunnah.com/tirmidhi:3036','hadith',locator='3036',hadith_grade='хасан по оценке Darussalam, приведённой Sunnah.com',isnad_note='Ат-Тирмизи называет передачу гариб и сообщает о других, мурсаль, путях без отца и деда Асыма.')
for key,explanation,anchor in [
('4:110','В рассказе Катады о краже у его дяди Рифаа этот аят даёт виновным возможность испросить прощение; речь не об обвинении самого Катады в краже.','попросит у Аллаха прощения'),
('4:111','Переданный Катадой рассказ включает этот принцип личной ответственности, противопоставленный попытке переложить вину за кражу.','тот совершил его во вред себе'),
('4:112','Рассказ Катады связывает аят с обвинением невиновного Лабида семьёй Бану Убайрик; Катада выступает заявителем и передатчиком.','обвинил в этом невиновного'),
('4:105','Рассказ Катады прямо приводит этот аят о справедливом разбирательстве и отказе защищать изменников после жалобы о краже.','Посему не препирайся за изменников'),
('4:106','В той же передаче просьба о прощении связана со словами, сказанными посланником Катаде до разъяснения дела.','Проси прощения у Аллаха')]:
    keep(204,1,key,explanation=explanation,anchor=anchor,basis='hadith_hasan_or_sahih',refs=[evidence],qualification='Именная связь по сообщению, оценённому хасан в Darussalam; ат-Тирмизи отмечает необычность полной цепочки и мурсаль-варианты. Имени Катады в арабском тексте аята нет; абсолютное отсутствие разногласий об иснаде не заявляется.')
